            "code": "# -*- coding: utf-8 -*-\nimport html\nimport json\nimport time\n\nclass AtlasAIAnalyzer:\n    &quot;&quot;&quot;\n    AtlasAIAnalyzer v16.8 - Core Universale Agnostico\n    Compila i nodi arricchendoli con le metriche pure estratte dai processori poliglotti.\n    &quot;&quot;&quot;\n    def __init__(self, analyzer, project_root):\n        self.analyzer = analyzer\n        self.project_root = project_root\n\n    def process_nodes(self, raw_nodes, target_lang, project_type, status_callback=None):\n        enriched_nodes = []\n        total_nodes = len(raw_nodes)\n\n        for index, node in enumerate(raw_nodes, start=1):\n            if status_callback: \n                status_callback(f&quot;Analisi Architetturale: {node[&#x27;id&#x27;]} ({index}/{total_nodes})&quot;, 45 + int((index/total_nodes)*45))\n            \n            ext = node[&#x27;ext&#x27;]\n            content = node[&#x27;content&#x27;]\n            deps = node[&#x27;deps&#x27;]\n            \n            processor = self.analyzer.get_processor(ext)\n            \n            # 1. Scansione degli hotspot prestazionali del linguaggio specifico\n            has_loops = processor.analyze_bottlenecks(content)\n            \n            # 2. Calcolo della presenza/densità (Agnostico: gestisce Unity o assegna 0 se Web/Python)\n            scene_objects = node.get(&#x27;scene_objects&#x27;, [&quot;__L_NONE__&quot;])\n            scene_density = len(scene_objects) if scene_objects != [&quot;__L_NONE__&quot;] else 0\n            \n            # 3. Compilazione metriche di accoppiamento (Defcon Matrix)\n            defcon = self.analyzer.compute_defcon_matrix(len(deps), scene_density, has_loops)\n            todos = self.analyzer.extract_todos(content, ext)\n            blueprint = processor.extract_pure_blueprint(content)\n            \n            # 4. Estrazione chirurgica dello scheletro strutturale puro (Niente corpi di metodi!)\n            slim_code = processor.extract_api_signature(content)\n            \n            expensive_methods = []\n            if has_loops:\n                expensive_methods.append(&quot;[HOTSPOT] Rilevata logica ad alta intensità d&#x27;esecuzione&quot;)\n\n            # Iniezione nel database JSON (atlas_data.js) letto da Vis.js e dal pannello AI\n            enriched_nodes.append({\n                &quot;id&quot;: node[&#x27;id&#x27;],\n                &quot;label&quot;: node[&#x27;id&#x27;],\n                &quot;layer&quot;: node[&#x27;layer&#x27;],\n                &quot;opacity&quot;: node[&#x27;opacity&#x27;],\n                &quot;scene_objects&quot;: scene_objects,\n                &quot;scene_density_count&quot;: scene_density,\n                &quot;code&quot;: html.escape(content),          # Sorgente intero per il pannello &#x27;Complete Source&#x27;\n                &quot;slim_code&quot;: html.escape(slim_code),    # SOLO la firma pura svuotata per il pannello &#x27;AI Suite&#x27;\n                &quot;description&quot;: html.escape(blueprint),  # Telemetria strategica\n                &quot;dependencies&quot;: &quot;, &quot;.join(deps) if deps else &quot;Nessuna&quot;,\n                &quot;todos&quot;: [html.escape(t) for t in todos],\n                &quot;is_god_object&quot;: len(deps) &gt;= 7,\n                &quot;dep_count&quot;: len(deps),\n                &quot;expensive_methods&quot;: expensive_methods,\n                &quot;has_heavy_loops&quot;: has_loops,\n                &quot;defcon_level&quot;: defcon\n            })\n        \n        return enriched_nodes\n\n    def export_llm_payload(self, nodes, output_html_path, project_type):\n        &quot;&quot;&quot;Esporta il contesto ridotto per l&#x27;iniezione nei modelli Ollama/OpenAI.&quot;&quot;&quot;\n        payload_path = output_html_path.replace(&quot;.html&quot;, &quot;_LLM_Payload.json&quot;)\n        payload_data = {\n            &quot;metadata&quot;: {\n                &quot;project_type&quot;: project_type, \n                &quot;generated_at&quot;: time.strftime(&quot;%Y-%m-%d %H:%M:%S&quot;),\n                &quot;engine_version&quot;: &quot;v16.8-Universal&quot;\n            },\n            &quot;modules&quot;: []\n        }\n        for n in nodes:\n            payload_data[&quot;modules&quot;].append({\n                &quot;module_id&quot;: n[&quot;id&quot;],\n                &quot;layer&quot;: n[&quot;layer&quot;],\n                &quot;defcon_risk&quot;: n.get(&quot;defcon_level&quot;, 1),\n                &quot;dependencies&quot;: n[&quot;dependencies&quot;].split(&quot;, &quot;) if n[&quot;dependencies&quot;] != &quot;Nessuna&quot; else [],\n                &quot;blueprint_signature&quot;: html.unescape(n[&quot;slim_code&quot;]) # Invia all&#x27;LLM solo le firme pulite\n            })\n        try:\n            with open(payload_path, &#x27;w&#x27;, encoding=&#x27;utf-8&#x27;) as f:\n                json.dump(payload_data, f, indent=4)\n            return payload_path\n        except Exception as e:\n            print(f&quot;Errore esportazione LLM payload: {e}&quot;)\n            return None",
